def total_charge(self) -> int:
    '''The total charge of the peptidoform ion, combining the charge carriers of
    :attr:`charge_state` with the charges localized on modifications
    (:attr:`local_charge`), as described in ProForma, section 11.5.

    Returns
    -------
    int
    '''
    charge_state = self.charge_state
    return self.local_charge + (charge_state.charge if charge_state is not None else 0)

